import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"21、【噬嗑】 震下離上","description":"周易集註 - 21、【噬嗑】 震下離上","frontmatter":{"title":"21、【噬嗑】 震下離上","description":"周易集註 - 21、【噬嗑】 震下離上"},"headers":[],"relativePath":"classics/jizhu/025.md","filePath":"classics/jizhu/025.md"}'),t={name:"classics/jizhu/025.md"};function h(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_21、【噬嗑】-震下離上" tabindex="-1">21、【噬嗑】 震下離上 <a class="header-anchor" href="#_21、【噬嗑】-震下離上" aria-label="Permalink to “21、【噬嗑】 震下離上”">​</a></h1><p>噬，齧也。嗑，合也。頤中有物間之，齧而後合也。上下兩陽而中虛，頤之象也。四一陽間於其中，頤中有物之象也。頤中有物，必齧而後合，噬嗑之象也。《序卦》：“嗑者合也，可觀而後有所合，所以次觀。”</p><p>噬嗑，亨，卦自有亨義也。天下之事，所以不得亨者，以其有間也。噬而嗑，則物不得而間之，自亨通矣，此概舉天下之事而言也。利用獄者，噬嗑中之一事也。</p><p>彖曰：頤中有物，曰噬嗑。噬嗑而亨，剛柔分，動而明，雷電合而章，柔得中而上行。雖不當位，利用獄也。</p><p>以卦體卦德二象卦綜釋卦名卦辭，頤中有物，則其物作梗，以人事論，如寇盜奸宄，治化之梗，蠻彝侵擾，疆場之梗，以至君臣父子，親戚朋友，離貳讒謗，間於其中者，皆頤中之梗也。易卦命名立象，各有所取。鼎也井也，大過之棟也，小過之飛鳥也，遠取諸物者也;艮之背也，頤之頤也，噬嗑頤中之物也，近取諸身者也。剛柔分者，震剛離柔，分居內外，內剛者齒也，外柔者輔也。動而明者，震動離明也。雷電合者，卦二象也。蓋動不如雷，則不能斷;明不如電，則不能察。惟雷電合，則雷震電耀，威明相濟，所謂動而明者，愈昭彰矣，此已前言噬嗑亨，柔得中而上行者。本卦綜賁，二卦同體，文王綜為一卦，故《雜卦》曰：“噬嗑食也，賁無色也。”言以賁下卦離之柔，得中上行，而居於噬嗑之上卦也，蓋不柔則失之暴，柔不中則失之縱，柔得中則寬猛得宜，有哀矜之念，而又不流於姑息，此其所以利用獄也。若依舊注，自益卦來，則非柔得中而上行，乃上行而柔得中矣。不當位者，以陰居陽也。</p><p>頤中有物，名噬嗑矣，而曰亨者，何也?蓋凡噬物，噬則頤分，嗑則頤合，今未噬之先，內剛外柔，將噬之際，動而明，正噬之時，合而章，先分後合，又何物得以間之，此所以噬嗑而亨也。然以噬嗑之亨，何事不利而獨利用獄者?蓋六五以柔在上，本不當位，不足以致諸事之利，獨以柔得中，所以利用獄也。</p><h3 id="《象》曰-雷電-噬嗑-先王以明罰敕法。" tabindex="-1">《象》曰：雷電，噬嗑，先王以明罰敕法。 <a class="header-anchor" href="#《象》曰-雷電-噬嗑-先王以明罰敕法。" aria-label="Permalink to “《象》曰：雷電，噬嗑，先王以明罰敕法。”">​</a></h3><p>罰者，一時所用之法。法者，平日所定之罰。明者辨也，辨其輕重，效電之明。敕者正也，正其國法，效電之威。明辨其墨劓剕宮大辟，以至流宥鞭樸金贖之數者，正所以振敕法度，使人知所畏避也。敕字本音賚，相承作敕。</p><p>初九，屨校滅趾，無咎。(校音教)</p><p>校，足械也。屨者，以械加於足，如納屨於足也。中爻坎，坎為桎梏，校之象也，故上九亦言校。趾者足趾也，震為足，趾之象也。滅者沒也，遮沒其趾也。變坤，不見其震之足，滅其趾之象也。無咎者，因其刑，而懲創以為善也。屨校不懲，必至荷校;滅趾不懲，必至滅耳。不因其刑而懲創，必至上九之惡積，罪大矣，安得無咎。初九上九，受刑之人，中四爻則用刑者。</p><p>九居初無位，下民之象也。以陽剛而不柔順，未有不犯刑者，故有屨校滅趾之象。趾乃人之所用以行者，懲之於初，使不得行其惡，小人之福也，故佔者無咎。</p><h3 id="《象》曰-屨校滅趾-不行也。" tabindex="-1">《象》曰：屨校滅趾，不行也。 <a class="header-anchor" href="#《象》曰-屨校滅趾-不行也。" aria-label="Permalink to “《象》曰：屨校滅趾，不行也。”">​</a></h3><p>震性動，滅其趾，則不得動而行以為惡矣。</p><p>六二，噬膚滅鼻，無咎。</p><p>膚者，肉外皮也。凡卦中次序相近者言膚，剝卦言膚者，艮七坤八也，睽卦言膚者，兌二離三也，此卦言膚者，離三震四也，六二之言膚者皮也，三言肉者，皮中之肉也。四言胏者，肉中連骨也，以陽剛也。五陰柔，又言肉矣，爻位以次漸深，噬肉以次漸難。祭有膚鼎，蓋柔脆而無骨，噬而易嗑者也。中四爻，有上下齒噬齧之象，故四爻皆言噬，此爻變兌，兌為口，噬之象也，二乃治獄之人，居其中，初在下，外為膚，噬其膚之象也，故《雜卦》曰“噬嗑食也”，正言此四爻之噬也。中爻艮，艮為鼻，鼻之象也。二變則中爻為離，不見其艮之鼻，滅其鼻之象也。滅字與滅趾滅耳同例，即朱子語錄所謂“噬膚而沒其鼻於器中”是也，言噬易嗑，而深噬之也。</p><p>六二柔順中正，聽斷以理，故其治獄有噬膚滅鼻之易之象，無咎之道也，故其佔如此。</p><h3 id="《象》曰-噬膚滅鼻-乘剛也。" tabindex="-1">《象》曰：噬膚滅鼻，乘剛也。 <a class="header-anchor" href="#《象》曰-噬膚滅鼻-乘剛也。" aria-label="Permalink to “《象》曰：噬膚滅鼻，乘剛也。”">​</a></h3><p>剛者，初之剛也。人剛則性直，獄內委曲皆不隱藏，己易於聽斷矣。六二又以中正乘其剛，以聽斷，必得其情，故有噬膚滅鼻之易。</p><p>六三，噬臘肉，遇毒，小吝，無咎。(臘音昔)</p><p>臘肉者，即六五之乾肉也，今人以鹽火幹之肉也。離火在前，三變又成離，上火下火，幹其肉之象也。九四六五，離有乾象，故二爻皆言幹，而此言臘也。遇者逢也，凡易中言遇者，皆雷與火也。睽九二變震，曰遇主於巷。遇元夫者，亦變震也，豐遇配主，遇彝主。小過大象坎錯離，遇其妣，遇其臣。此雷火，故言遇毒，毒者臘肉之陳久太肥者也。《說文》雲：“毒者厚也。”《五行志》雲：“厚味實臘毒。”師古云：“臘，久也。味厚者為毒久。”文選張景陽七命雲：“甘臘毒之味是也。”噬臘遇毒者，言噬乾肉而遇陳久太肥厚味之肉也。中爻坎，所以曰毒，故師卦有此毒字。</p><p>六三陰柔，不中不正，治獄而遇多年陳久煩瑣之事，一時難於斷理，故有噬臘遇毒之象，亦小有吝矣，然時當噬嗑，於義亦無咎，故其佔又如此。</p><h3 id="《象》曰-遇毒-位不當也。" tabindex="-1">《象》曰：遇毒，位不當也。 <a class="header-anchor" href="#《象》曰-遇毒-位不當也。" aria-label="Permalink to “《象》曰：遇毒，位不當也。”">​</a></h3><p>以陰居陽。</p><p>九四，噬幹胏，得金矢，利艱貞，吉。(乾音幹，胏音滓)</p><p>胏，乾肉之有骨者。離為幹，幹之象也，六五亦同此象。三肉居卦之中，乃獄情之難服者，故皆以堅物象之。金者剛也，此爻正頤中之物，陽金居二陰之間，金之象也。變坤錯幹，亦金之象也。矢者直也，中爻坎，矢之象也。蓋九四正居坎之中，坎得幹之中爻，為中男，故此爻有金象，有矢象，若六五變為幹，止有金象，無矢矣，故止曰得黃金。且九四剛而不正，故戒之以剛直。六五柔中，故戒之以剛中。二爻皆曰得者，教人必如此也。艱者，凜凜然惟恐一毫之少忽，以心言也。貞者，兢兢然惟恐一毫之不正，以事言也。周公此象蓋極精者，非周禮鈞金束矢之說也。</p><p>四居卦中，獄情甚難，故有噬幹胏堅物之象。四以剛明之才，治之宜即吉矣。但四弱於二陰之間，恐其徇於私而未甚光明，故必如金之剛，矢之直，而又艱難正固，則吉矣。因九四不中正，故教佔者，佔中之象又如此。</p><h3 id="《象》曰-利艱貞-吉-未光也。" tabindex="-1">《象》曰：利艱貞，吉，未光也。 <a class="header-anchor" href="#《象》曰-利艱貞-吉-未光也。" aria-label="Permalink to “《象》曰：利艱貞，吉，未光也。”">​</a></h3><p>未光，即屯九五，夬九五之類。</p><p>六五，噬乾肉，得黃金，貞厲，無咎。</p><p>噬乾肉，難於膚，而易於幹胏者也，乃所治之獄，匪難匪易之象。黃者中也，金者剛也，變幹，金之象也。幹錯坤，黃之象也。離得坤之中爻為中女，則離之中，乃坤土也，故曰黃金。貞者純乎天理之公而無私也，厲者存乎危懼之心而無忽也，無咎者刑罰當而民不冤也。</p><p>六五居尊，用刑于人，人無不服，故有噬乾肉易嗑之象，然恐其柔順而不斷也，故必如黃之中，金之剛，而又貞厲，乃得無咎，因六五柔中，故戒佔者佔中之象又如此。</p><h3 id="《象》曰-貞厲無咎-得當也。-當去聲" tabindex="-1">《象》曰：貞厲無咎，得當也。(當去聲) <a class="header-anchor" href="#《象》曰-貞厲無咎-得當也。-當去聲" aria-label="Permalink to “《象》曰：貞厲無咎，得當也。(當去聲)”">​</a></h3><p>言必如此治獄方得當也。</p><p>上九，何校滅耳，兇。(何音荷)</p><p>何者負也，謂在頸也。中爻坎為桎梏，初則曰屨，上則曰負，以人身分上下而言也。滅者，遮滅其耳也。坎為耳痛，滅耳之象也。又離為戈兵，中爻艮為手，手持戈兵，加於耳之上，亦滅耳之象也。</p><p>上九居卦之上，當獄之終，蓋惡極罪大，怙終不悛者也，故有何校滅耳之象，佔者如此，兇可知矣。</p><h3 id="《象》曰-何校滅耳-聰不明也。" tabindex="-1">《象》曰：何校滅耳，聰不明也。 <a class="header-anchor" href="#《象》曰-何校滅耳-聰不明也。" aria-label="Permalink to “《象》曰：何校滅耳，聰不明也。”">​</a></h3><p>聦者聞也，聽也。上九未變，離明在上，坎耳在下，故聽之明。今上九既變，則不成離明矣，所以聽之不明也。困卦坎有言不信，夬四變坎，聞言不信，今既聽之不明，則不信人言矣。坎既心險，又不信好言，所以犯大罪。</p>',38)])])}const f=e(t,[["render",h]]);export{_ as __pageData,f as default};
